@page "/dashboard"
@using sv_8331ad039cbe478b9608a46ba6173c2b.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text">
            Selected: <strong>@GetWarehouseName()</strong> (@WarehouseState.CurrentWarehouseId)
        </p>
    </div>
</div>

<div class="card mt-3">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            Items below minimum level:
            <span class="badge bg-warning text-dark fs-5">@AlertService.CurrentLowStockCount</span>
        </p>
        <p class="text-muted"><small>Refreshes every 10 seconds. Last update: @_lastUpdate.ToString("HH:mm:ss")</small></p>
    </div>
</div>

@code {
    private DateTime _lastUpdate = DateTime.Now;

    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleStateChanged;
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
        AlertService.Subscribe();
    }

    private void HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void HandleAlertDataChanged()
    {
        _lastUpdate = DateTime.Now;
        InvokeAsync(StateHasChanged);
    }

    private string GetWarehouseName()
    {
        return WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId)?.Name ?? "Unknown";
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleStateChanged;
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
        AlertService.Unsubscribe();
    }
}

